// Central config. Run with: node --env-file-if-exists=.env src/server.js  (see notes/SCRAPING_GUIDELINES.md §1)
const list = (v) => (v || '').split(',').map((s) => s.trim()).filter(Boolean);

export const config = {
  port: Number(process.env.PORT || 4000),
  // "projectName:key,projectName:key" — each site gets its own key so stats are per project
  // or SCRAPELAB_KEY_<PROJECT>=key (one env var per project, e.g. generated by Render)
  apiKeys: {
    ...Object.fromEntries(list(process.env.SCRAPELAB_KEYS).map((p) => p.split(':'))),
    ...Object.fromEntries(
      Object.entries(process.env)
        .filter(([k, v]) => k.startsWith('SCRAPELAB_KEY_') && v)
        .map(([k, v]) => [k.slice('SCRAPELAB_KEY_'.length).toLowerCase(), v]),
    ),
  },
  firecrawlUrl: process.env.FIRECRAWL_URL || '', // e.g. http://localhost:3002 (self-hosted)
  firecrawlKey: process.env.FIRECRAWL_API_KEY || '',
  userAgent: process.env.USER_AGENT || 'scrapelab/0.1 (+https://github.com/danieljohnfas/akilibrain/tree/main/scrapelab)',
  minDomainIntervalMs: Number(process.env.MIN_DOMAIN_INTERVAL_MS || 2000),
  fetchTimeoutMs: Number(process.env.FETCH_TIMEOUT_MS || 15000),
  // Guidelines §6/§8: known-blocked / low-yield hosts are refused up front
  blocklist: list(process.env.BLOCKLIST || 'glassdoor.com,youtube.com,tiktok.com'),
  statsFile: process.env.STATS_FILE || 'data/stats.json',
};
